// Package postgres implements the operator domain's grant and
// authority stores against PostgreSQL via jackc/pgx. The queries are
// generated by sqlc from queries.sql.
package postgres

import (
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/errorx"
	"github.com/garamsh/garam/platform/internal/operator/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
)

// Store implements operator.GrantStore and operator.AuthorityStore.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// New constructs a Postgres-backed grant and authority store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

// storageError classifies a driver error as pgxerr does, and reports a
// failure it cannot name as unavailable: authority read from storage
// that did not answer is unknown, and unknown refuses (#1160).
func storageError(err error, op string, notFound, conflict error) error {
	err = pgxerr.Classify(err, op, notFound, conflict)
	if err != nil && errorx.KindOf(err) == errorx.KindUnknown {
		return errorx.Wrap(err, op, errorx.KindUnavailable)
	}
	return err
}

func optionalText(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}
